  selector: 'app-my-shared-component', // Use the app- prefix to avoid conflicts with other components
  template: '<p>This is a shared component!</p>'
})
export class MySharedComponent {
  // Component logic goes here
}
```
The `selector` property specifies the CSS selector that Angular uses to identify the component in your Angular application.

