```csharp
using System;
using System.Net;
using System.Net.Http;
using System.Text;
using System.Threading;

class HelloServer
{
    static void Main(string[] args)
    {
        // Créer un nouveau listenner sur le port 8080
        HttpListener listener = new HttpListener();
        listener.Prefixes.Add("http://localhost:8080/");

        // Démarrer le serveur
        listener.Start();

        Console.WriteLine("Server started. Listening on port 8080...");

        // Traiter les requêtes
        while (true)
        {
            HttpListenerContext context = listener.GetContext();
            HttpListenerRequest request = context.Request;

            // Traitement de la requête
            if (request.Url.AbsolutePath == "/hello")
            {
                // Envoyer une réponse HTTP avec le message "Hello"
                using (HttpListenerResponse response = context.Response)
                {
                    byte[] buffer = Encoding.UTF8.GetBytes("Hello, world!");
                    response.ContentLength64 = buffer.Length;
                    using (StreamWriter writer = new StreamWriter(response.OutputStream))
                    {
                        writer.Write(Encoding.UTF8.GetString(buffer));
                    }
                }
            }
            else
            {
                // Envoyer une erreur HTTP 404
                using (HttpListenerResponse response = context.Response)
                {
                    byte[] buffer = Encoding.UTF8.GetBytes("Not found!");
                    response.StatusCode = 404;
                    response.ContentLength64 = buffer.Length;
                    using (StreamWriter writer = new StreamWriter(response.OutputStream))
                    {
                        writer.Write(Encoding.UTF8.GetString(buffer));
                    }
                }
            }
        }
    }
}
```
